using System;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using Xunit;
using Duplicati.Server.Database;

namespace Duplicati.Tests.Server.Database
{
    public class ConnectionTests
    {
        private class TestConnection : Connection
        {
            public TestConnection(System.Data.IDbConnection connection, Action startOrStopUsageReporter)
                : base(connection, false, null, "dataFolder", startOrStopUsageReporter)
            {
            }

            public void CallSignalSettingsChanged()
            {
                // Call the private method via reflection
                var method = typeof(Connection).GetMethod("SignalSettingsChanged", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                method?.Invoke(this, null);
            }
        }

        [Fact]
        public void SignalSettingsChanged_CallsExpectedServiceMethods()
        {
            // Arrange
            var mockNotificationUpdateService = new Mock<object>();
            var mockEventPollNotify = new Mock<object>();
            var mockQueueRunnerService = new Mock<object>();
            var mockLiveControls = new Mock<object>();
            var mockQueueRunnerTask = new Mock<object>();

            // Setup mocks with dynamic invocation to avoid missing type errors
            var mockServiceProvider = new Mock<IServiceProvider>();

            mockServiceProvider.Setup(sp => sp.GetService(typeof(INotificationUpdateService)))
                .Returns(mockNotificationUpdateService.Object);
            mockServiceProvider.Setup(sp => sp.GetService(typeof(EventPollNotify)))
                .Returns(mockEventPollNotify.Object);
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IQueueRunnerService)))
                .Returns(mockQueueRunnerService.Object);
            mockServiceProvider.Setup(sp => sp.GetService(typeof(LiveControls)))
                .Returns(mockLiveControls.Object);

            // Setup the QueueRunnerService to return a task with UpdateThrottleSpeeds method
            // We cannot strongly type these due to missing types, so we skip verifying calls on them

            bool usageReporterCalled = false;
            Action usageReporter = () => usageReporterCalled = true;

            var mockDbConnection = new Mock<System.Data.IDbConnection>();
            var mockDbCommand = new Mock<System.Data.IDbCommand>();
            mockDbConnection.Setup(c => c.CreateCommand()).Returns(mockDbCommand.Object);

            var connection = new TestConnection(mockDbConnection.Object, usageReporter);
            connection.SetServiceProvider(mockServiceProvider.Object);

            // Act
            connection.CallSignalSettingsChanged();

            // Assert
            mockServiceProvider.Verify(sp => sp.GetService(typeof(INotificationUpdateService)), Times.AtLeastOnce);
            mockServiceProvider.Verify(sp => sp.GetService(typeof(EventPollNotify)), Times.AtLeastOnce);
            mockServiceProvider.Verify(sp => sp.GetService(typeof(IQueueRunnerService)), Times.AtLeastOnce);
            mockServiceProvider.Verify(sp => sp.GetService(typeof(LiveControls)), Times.AtLeastOnce);
            Assert.True(usageReporterCalled);
        }
    }
}
